'use client';

// src/pages/LoginPage.tsx adapted for Next.js
import React, { useState, lazy, Suspense } from 'react';
import Logo from '@/components/Logo';
import RoomButton from '@/components/RoomButton';
import BackHandle from '@/hooks/BackHandle';

// Lazy-loaded heavy components
const CreateRoom = lazy(() => import('@/features/lobby/CreateRoomForm'));
const JoinRoom = lazy(() => import('@/features/lobby/JoinRoomForm'));
const LogoBigView = lazy(() => import('@/components/LogoBigView'));

export default function LoginPage() {
    const [createButtonActive, setCreateButtonActive] = useState<boolean>(false);
    const [joinButtonActive, setJoinButtonActive] = useState<boolean>(false);

    return (
        <div className="h-screen overflow-hidden bg-[url('/nexConnect05.svg')] bg-center bg-cover">
            <div className="flex h-full w-full">
                {/* Main Content Area */}
                <div className="w-full lg:w-1/2 h-full flex items-center justify-center p-4">
                    <div className="w-full max-w-[400px] transition-all h-full flex flex-col justify-center">
                        {/* Logo: Visible on small screens (< lg) */}
                        <div className="lg:hidden mb-8 flex justify-center">
                            <Logo />
                        </div>

                        <Suspense fallback={<div className="text-center">Loading...</div>}>
                            {joinButtonActive ? (
                                <>
                                    <JoinRoom />
                                    <BackHandle active={setJoinButtonActive} />
                                </>
                            ) : createButtonActive ? (
                                <>
                                    <CreateRoom />
                                    <BackHandle active={setCreateButtonActive} />
                                </>
                            ) : (
                                <>
                                    <RoomButton Active={setCreateButtonActive} IDE="Create" />
                                    <RoomButton Active={setJoinButtonActive} IDE="Join" />
                                </>
                            )}
                        </Suspense>
                    </div>
                </div>

                {/* Side Logo: Visible on large screens (lg+) */}
                <div className="hidden lg:flex w-1/2 h-full items-center justify-center">
                    <Suspense fallback={null}>
                        <LogoBigView />
                    </Suspense>
                </div>
            </div>
        </div>
    );
}
